<script setup>
import { onMounted, reactive, ref } from 'vue'
import { CheckCircle2, Headphones, LoaderCircle, MessageSquareReply, RefreshCw } from 'lucide-vue-next'
import BaseModal from '../components/BaseModal.vue'
import { assignTicket, closeTicket, getTickets, replyTicket } from '../services/customerService.js'
import { showToast } from '../utils.js'

const rows=ref([]),total=ref(0),loading=ref(false),processing=ref(false),open=ref(false),selected=ref(null),reply=ref(''),remark=ref('问题已处理完成')
const filters=reactive({status:'OPEN',page:1,size:20})
const meta=s=>({OPEN:['待领取','warning'],PROCESSING:['处理中','info'],CLOSED:['已关闭','success']}[s]||[s,''])
async function load(){loading.value=true;try{const data=await getTickets(filters);rows.value=data.records||[];total.value=Number(data.total||0)}catch(e){showToast(e.message)}finally{loading.value=false}}
function detail(row){selected.value=row;reply.value='';open.value=true}
async function assign(){processing.value=true;try{selected.value=await assignTicket(selected.value.id);showToast('工单已领取，处理人来自当前 Admin 登录态');await load()}catch(e){showToast(e.message)}finally{processing.value=false}}
async function sendReply(){if(reply.value.trim().length<2)return showToast('请填写至少 2 个字的回复');processing.value=true;try{selected.value=await replyTicket(selected.value.id,reply.value.trim());reply.value='';showToast('回复已发送，用户站内通知已生成');await load()}catch(e){showToast(e.message)}finally{processing.value=false}}
async function close(){processing.value=true;try{selected.value=await closeTicket(selected.value.id,remark.value.trim());showToast('工单已关闭并通知用户');await load()}catch(e){showToast(e.message)}finally{processing.value=false}}
onMounted(load)
</script>

<template><div class="page"><div class="page-head"><div><div class="eyebrow"><Headphones/> CUSTOMER SERVICE</div><h1>客服工单</h1><p>领取、回复和关闭用户咨询与投诉；所有处理身份以 Admin Token 为准。</p></div><button class="btn" @click="load"><LoaderCircle v-if="loading" class="spin"/><RefreshCw v-else/>刷新工单</button></div><div class="grid cols-3 audit-metrics"><div class="metric compact-metric"><Headphones/><span><small>当前筛选</small><b>{{total}}</b></span></div><div class="metric compact-metric"><MessageSquareReply/><span><small>回复通知</small><b>自动</b></span></div><div class="metric compact-metric"><CheckCircle2/><span><small>处理幂等</small><b>已启用</b></span></div></div><section class="panel"><div class="panel-head"><div><h2>工单队列</h2><p>OPEN → PROCESSING → CLOSED</p></div><span class="endpoint">GET /v1/admin/customer-service/tickets</span></div><div class="toolbar"><select v-model="filters.status" class="field" @change="load"><option value="">全部状态</option><option value="OPEN">待领取</option><option value="PROCESSING">处理中</option><option value="CLOSED">已关闭</option></select></div><div v-if="!rows.length" class="empty-note"><Headphones/><p>当前状态下没有工单</p></div><div v-else class="table-wrap"><table><thead><tr><th>工单 / 用户</th><th>场景与引用</th><th>标题</th><th>状态</th><th>处理人</th><th>操作</th></tr></thead><tbody><tr v-for="row in rows" :key="row.id"><td><b>#{{row.id}}</b><small>用户 {{row.creatorId}}</small></td><td>{{row.scene}}<small>{{row.targetType}} {{row.targetId}}</small></td><td>{{row.title}}</td><td><span class="status" :class="meta(row.ticketStatus)[1]">{{meta(row.ticketStatus)[0]}}</span></td><td>{{row.assignedAdminId||'—'}}</td><td><button class="btn sm" @click="detail(row)">处理</button></td></tr></tbody></table></div></section><BaseModal :open="open" title="客服工单详情" @close="open=false"><template v-if="selected"><div class="detail-grid"><div class="detail-item"><small>工单 ID</small><b>{{selected.id}}</b></div><div class="detail-item"><small>状态</small><b>{{meta(selected.ticketStatus)[0]}}</b></div></div><div class="code-note">{{selected.content}}</div><div v-for="message in selected.messages" :key="message.id" class="notice-box" style="margin-top:10px"><b>{{message.senderType}}</b> · {{message.content}}</div><div v-if="selected.ticketStatus==='PROCESSING'" class="form-group" style="margin-top:14px"><label>回复用户</label><textarea v-model="reply" class="field" maxlength="2048"></textarea></div><div v-if="selected.ticketStatus==='PROCESSING'" class="form-group"><label>关闭备注</label><input v-model="remark" class="field" maxlength="255"></div></template><template #footer><button class="btn" @click="open=false">关闭窗口</button><button v-if="selected?.ticketStatus==='OPEN'" class="btn primary" :disabled="processing" @click="assign">领取工单</button><button v-if="selected?.ticketStatus==='PROCESSING'" class="btn" :disabled="processing" @click="sendReply">发送回复</button><button v-if="selected?.ticketStatus==='PROCESSING'" class="btn success solid" :disabled="processing" @click="close">完成并关闭</button></template></BaseModal></div></template>
